import {markdown,enhanceMarkdown} from '/rich-text.js';
import {libraryIcon} from '/agent-appearance.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const words=v=>String(v||'').replaceAll('_',' ');
const reasonLabels={'connection-unavailable':'Choose a Jev connection in Project settings → AI & context.','connection-rejected':'The Jev connection was rejected. Check its credentials in Project settings.','missing-evidence':'Add a role description or assigned duties before using Auto.','no-confident-match':'No pack matched strongly enough. Use the base view or choose a pack manually.','invalid-model-answer':'Jev returned an invalid answer. Manual pins remain available.','service-timeout':'Jev did not respond in time. Manual pins remain available.','service-unavailable':'Jev is unavailable. Manual pins remain available.','integration-error':'The selection request was rejected. Check the local decision audit.','audit-unavailable':'The decision could not be recorded. Check local storage.','rate-limit':'Selection is rate limited. Try again later; no automatic retry is scheduled.','service-busy':'Other selections are running. Try again shortly.','input-limit':'The role brief exceeds the selection budget. Choose packs manually.'};
function referenceHTML(source){
  if(!source)return '';
  return `<details class="rp-source"><summary>Source${source.revision!==undefined?' · revision '+esc(source.revision):''}</summary><dl>${Object.entries(source).map(([key,value])=>`<div><dt>${esc(words(key))}</dt><dd>${esc(value??'Unknown')}</dd></div>`).join('')}</dl></details>`;
}
export function rolePanelHTML(panel){
  return `<article class="rp-workspace rp-${esc(panel.color)}"><header class="rp-workspace-head"><span class="rp-emblem" aria-hidden="true">${libraryIcon(panel.icon,28)}</span><div><p class="rp-eyebrow">${esc(panel.eyebrow)}</p><h3>${esc(panel.name)}</h3><p>${esc(panel.description)}</p></div></header><div class="rp-metrics">${panel.metrics.map(m=>`<div><strong>${esc(m.value)}</strong><span>${esc(m.label)}</span></div>`).join('')}</div><div class="rp-sections">${panel.sections.map((s,index)=>`<section class="rp-section"><header><span class="rp-section-index" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><h4>${esc(s.title)}</h4><span class="rp-count">${esc(s.total)}</span></header>${s.items.length?`<div class="rp-records">${s.items.map(item=>`<article class="rp-record ${item.eligible===false?'rp-unavailable':''}"><div class="rp-record-heading"><strong>${esc(item.title)}</strong>${item.status?`<span class="rp-status rp-status-${esc(item.status)}">${esc(words(item.status))}</span>`:''}</div><p class="rp-record-label">${esc(item.label)}${item.by?' · '+esc(item.by):''}${item.owner?' · '+esc(item.owner):''}</p><div class="rp-record-text">${markdown(item.text||'No evidence recorded.',{literalHtml:true})}</div>${item.detail?`<p class="rp-record-detail">${esc(item.detail)}</p>`:''}${referenceHTML(item.source)}</article>`).join('')}</div>${s.total>s.items.length?`<p class="rp-note">Showing ${s.items.length} of ${s.total}. Read the shared board or notebook for the remaining records.</p>`:''}`:`<div class="rp-empty"><span aria-hidden="true">${libraryIcon('circle-dashed',22)}</span><p>${esc(s.empty)}</p></div>`}</section>`).join('')}</div><details class="rp-guide"><summary>${libraryIcon('compass',18)} Role guide <span>v${esc(panel.version)}</span></summary><ol>${panel.guide.map(g=>`<li>${esc(g)}</li>`).join('')}</ol><p>Guidance does not change task scope or permission. Claude can read it with <code>role_pack_view</code>.</p></details><footer class="rp-provenance"><span>${libraryIcon('history',14)} Updated ${esc(new Date(panel.at).toLocaleTimeString())}</span><span>${panel.sources.length?panel.sources.map(s=>esc(s.title)+' · r'+esc(s.revision)).join(' / '):'No active shared plan'}</span><small>${esc(panel.scope)}</small></footer></article>`;
}
export class RolePackDialog {
  constructor(button,data,{api,onClose}){
    if(!document.querySelector('link[data-role-pack-styles]')){const style=document.createElement('link');style.rel='stylesheet';style.href='/role-packs.css';style.dataset.rolePackStyles='';document.head.append(style);}
    Object.assign(this,{button,data,api,onClose});this.mode=data.config.mode;this.pinned=[...data.config.pinned];this.tab=data.panels.length?'workspace':'configure';this.selected=data.panels[0]?.id;
    this.element=document.createElement('dialog');this.element.className='role-pack-dialog';this.element.setAttribute('aria-label',data.role+' role packs');document.body.append(this.element);
    this.element.addEventListener('cancel',e=>{e.preventDefault();if(!this.busy)this.close();});
    this.element.addEventListener('click',e=>{const b=e.target.closest('[data-rp-action]');if(b)this.action(b.dataset.rpAction,b).catch(error=>this.error(error));});
    this.element.addEventListener('change',e=>{if(e.target.name==='role-pack-mode'){this.mode=e.target.value;this.render();}if(e.target.name==='role-pack-pin'){if(e.target.checked)this.pinned.push(e.target.value);else this.pinned=this.pinned.filter(id=>id!==e.target.value);this.render();}});
    this.render();this.element.showModal();
  }
  render(){
    const focused=this.element.contains(document.activeElement)?document.activeElement:null,focusKey=focused?{name:focused.name,value:focused.value,action:focused.dataset.rpAction,id:focused.dataset.id}:null;
    const d=this.data,selection=d.selection,active=d.panels.find(p=>p.id===this.selected)||d.panels[0],pinned=this.pinned.length;
    this.element.innerHTML=`<header class="rp-dialog-head"><div><span class="rp-eyebrow">Claude Mods · ${esc(d.role)}</span><h2>Role workspaces</h2></div><button type="button" class="rp-close" data-rp-action="close" aria-label="Close role packs" ${this.busy?'disabled':''}>${libraryIcon('x',22)}</button></header><div class="rp-tabs" role="tablist" aria-label="Role workspace views"><button type="button" id="rp-workspace-tab" role="tab" aria-controls="rp-content" aria-selected="${this.tab==='workspace'}" data-rp-action="workspace">${libraryIcon('panels-top-left',17)} Workspace ${d.panels.length?`<span>${d.panels.length}</span>`:''}</button><button type="button" id="rp-configure-tab" role="tab" aria-controls="rp-content" aria-selected="${this.tab==='configure'}" data-rp-action="configure">${libraryIcon('sliders-horizontal',17)} Choose packs</button></div><div class="rp-body" id="rp-content" role="tabpanel" aria-labelledby="rp-${this.tab}-tab">${this.tab==='workspace'?`<div class="rp-selection-strip"><span class="rp-selection-dot" aria-hidden="true"></span><div><strong>${esc(selection.source||'Off')}</strong><p>${esc(reasonLabels[selection.reason]||selection.reason)}</p></div><button type="button" data-rp-action="reload" ${this.busy?'disabled':''}>${libraryIcon('refresh-cw',16)} Refresh view</button></div>${d.panels.length?`<div class="rp-pack-tabs" role="group" aria-label="Active role packs">${d.panels.map(p=>`<button type="button" class="rp-pack-tab rp-${esc(p.color)}" data-rp-action="select" data-id="${p.id}" aria-pressed="${active?.id===p.id}">${libraryIcon(p.icon,18)} ${esc(p.name)}${d.config.pinned.includes(p.id)?`<span title="Manually pinned">${libraryIcon('pin',13)}</span>`:''}</button>`).join('')}</div>${rolePanelHTML(active)}`:`<div class="rp-blank"><span class="rp-blank-mark">${libraryIcon('layers',40)}</span><h3>${selection.status==='off'?'A workspace for your agent’s role':'No active role pack'}</h3><p>${d.eligible.ok?'Choose a pack yourself, or let Jev match the agent’s duties. Your current chat and activity cards stay available.':esc(d.eligible.reason)}</p><button type="button" class="primary" data-rp-action="configure">Choose packs</button></div>`}`:this.configurationHTML()}
      <p class="rp-native-note">${libraryIcon('terminal',15)} ${d.native.current?'Native Mod synchronized. Open /heloscrum → Roles in Claude.':'Native view updates on its next turn boundary or /heloscrum refresh. Older sessions may need an idle restart to load this Mod version.'}</p></div><footer class="rp-dialog-foot"><p class="rp-feedback" role="status">${this.busy?'Updating role packs…':esc(this.feedback||'')}</p><p class="rp-error" role="alert"></p><small>${esc(d.authority)}</small></footer>`;
    const tabs=[...this.element.querySelectorAll('[role=tab]')];tabs.forEach((tab,i)=>{tab.tabIndex=tab.getAttribute('aria-selected')==='true'?0:-1;tab.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;this.tab=tabs[n].dataset.rpAction;this.render();this.element.querySelector('[aria-selected=true]')?.focus();}});});
    enhanceMarkdown(this.element,()=>{},{project:d.project,taskId:d.taskId}).catch(()=>{});
    this.restoreFocus(focusKey);
  }
  restoreFocus(key){if(!key)return;const match=[...this.element.querySelectorAll('input,button')].find(el=>key.name?el.name===key.name&&el.value===key.value:key.action&&el.dataset.rpAction===key.action&&el.dataset.id===key.id);if(match&&!match.disabled)match.focus({preventScroll:true});}
  configurationHTML(){
    const d=this.data,disabled=this.busy||!d.eligible.ok,limit=this.pinned.length>=d.policy.maxActive;
    return `<section class="rp-configuration"><h3>Give this role its own view</h3><p>Combine any of the ${d.catalog.length} installed workspaces. Pins always take precedence.</p>${!d.eligible.ok?`<p class="rp-warning">${esc(d.eligible.reason)}. A Claude model running through another provider cannot load Claude Code Mods.</p>`:''}<fieldset class="rp-mode-options" ${this.busy?'disabled':''}><legend>Selection mode</legend>${[['off','Off','Keep the base activity view'],['manual','Manual','Choose your packs'],['auto','Jev Auto','Match the assigned duties']].map(([value,label,hint])=>`<label><input type="radio" name="role-pack-mode" value="${value}" ${value===this.mode?'checked':''} ${disabled&&value!=='off'?'disabled':''}><span><strong>${label}</strong><small>${hint}</small></span></label>`).join('')}</fieldset>${this.mode==='auto'?`<div class="rp-auto-note">${libraryIcon('sparkles',20)}<div><strong>${d.jevAvailable?'Jev is connected':'Jev connection needed'}</strong><p>Auto sends a bounded role description and assigned duties to your configured Jev service. It can select none. Manual pins stay selected. Auto adds every matching pack; no model call is needed when all packs are pinned.</p><small>Reuses unchanged decisions. At most ${d.policy.maxAttemptsPerHour} calls per hour per agent, ${d.policy.timeoutMs/1000}s timeout. Refreshing the view makes no model call.</small></div></div>`:''}<fieldset class="rp-picker" ${disabled||this.mode==='off'?'disabled':''}><legend>${this.mode==='auto'?'Optional manual pins':'Available role packs'} <span>${this.pinned.length} / ${d.policy.maxActive}</span></legend><div class="rp-pack-grid">${d.catalog.map(p=>`<label class="rp-pack-option rp-${esc(p.color)}"><input type="checkbox" name="role-pack-pin" value="${p.id}" ${this.pinned.includes(p.id)?'checked':''} ${limit&&!this.pinned.includes(p.id)?'disabled':''}><span class="rp-pack-option-icon">${libraryIcon(p.icon,24)}</span><span class="rp-pack-copy"><strong>${esc(p.name)}</strong><small>${esc(p.description)}</small></span><span class="rp-check" aria-hidden="true">${libraryIcon('check',15)}</span></label>`).join('')}</div></fieldset><div class="rp-config-actions"><button type="button" class="primary" data-rp-action="save" ${this.busy||!d.eligible.ok&&this.mode!=='off'||this.mode==='manual'&&!this.pinned.length?'disabled':''}>Save role packs</button>${d.config.mode==='auto'&&this.mode==='auto'&&JSON.stringify(this.pinned)===JSON.stringify(d.config.pinned)?`<button type="button" data-rp-action="evaluate" ${this.busy?'disabled':''}>Re-evaluate duties</button>`:''}<span>Saving never restarts a working agent.</span></div>${d.selection.scores?`<details class="rp-decision"><summary>Jev selection record</summary><p>${esc(d.selection.model)} · ${esc(d.selection.at)} · policy ${esc(d.selection.policyVersion)} · threshold ${d.selection.threshold}</p><ul>${d.catalog.map(p=>`<li><span>${esc(p.name)}</span><span>${Math.round(d.selection.scores[p.id]*100)}% yes</span></li>`).join('')}</ul><p>${d.selection.usage?`${esc(d.selection.usage.input_tokens??'Unknown')} input / ${esc(d.selection.usage.output_tokens??'Unknown')} output tokens`:'Usage not returned'}. These are applicability judgments, not workflow success probabilities.</p></details>`:''}</section>`;
  }
  error(error){if(!this.closed)this.element.querySelector('.rp-error').textContent=error.message;}
  async action(action,button){
    if(this.busy)return;
    if(action==='close')return this.close();
    if(action==='workspace'||action==='configure'){this.tab=action;this.render();this.element.querySelector('[aria-selected=true]')?.focus();return;}
    if(action==='select'){this.selected=button.dataset.id;this.render();this.element.querySelector('[data-id="'+this.selected+'"]')?.focus();return;}
    this.busy=true;this.feedback='';this.render();
    try{
      if(action==='save')this.data=await this.api('role-packs/configure',{id:this.data.taskId,expectedRevision:this.data.config.revision,mode:this.mode,pinned:this.pinned});
      else if(action==='evaluate')this.data=await this.api('role-packs/refresh',{id:this.data.taskId,expectedRevision:this.data.config.revision});
      else this.data=await this.api('role-packs?task='+this.data.taskId);
      this.mode=this.data.config.mode;this.pinned=[...this.data.config.pinned];this.feedback=action==='save'?'Role-pack preferences saved.':action==='evaluate'?'Selection checked.':'View refreshed without a model call.';
      if(action==='save')this.tab='workspace';
    }catch(error){this.busy=false;this.render();this.error(error);return;}
    this.busy=false;this.render();
  }
  close(){if(this.closed)return;this.closed=true;this.element.close();this.element.remove();this.button?.focus({preventScroll:true});this.onClose?.();}
}
